PLAYGROUND_VALUE_OPTS = {"--grammar-path", "-e", "--export"}
COMPLETE_VALUE_OPTS = {"-s", "--shell"}
DUMP_VALUE_OPTS = {"--config-path"}
'''
s=s.replace(marker,replacement)
# command parse_options replacements
repls={
"parse_options(args)
    if missing:
        return clap_error(f"a value is required for '{missing} <CONFIG_PATH>'": "parse_options(args, DUMP_VALUE_OPTS)
    if missing:
