    if len(pos) > 1:
        return clap_error(f"unexpected argument '{pos[1]}' found", "Usage: executable generate",
"parse_options(args)
    dbg =": "parse_options(args, PARSE_VALUE_OPTS)
    dbg =",
"parse_options(args)
    if not pos:
        eprintln("error: the following required arguments were not provided:")": "parse_options(args, QUERY_VALUE_OPTS)
    if not pos:
        eprintln("error: the following required arguments were not provided:")",
"parse_options(args)
    enc = opts.get("--encoding")": "parse_options(args, HIGHLIGHT_VALUE_OPTS if cmd == "highlight" else TAGS_VALUE_OPTS)
    enc = opts.get("--encoding")",
"parse_options(args)
    bump = opts.get("--bump")": "parse_options(args, VERSION_VALUE_OPTS)
    bump = opts.get("--bump")",
"parse_options(args)
    stat = opts.get("--stat")": "parse_options(args, FUZZ_VALUE_OPTS if cmd == "fuzz" else TEST_VALUE_OPTS)
    stat = opts.get("--stat")",
